        c = (int)((float)i * 0.25f * f + *(float *)(unsigned)&ai_Unk5eb988);
        id = d2_CreateWinText(3, c);
        *(unsigned short *)(*(int *)(unsigned)&d2_Objs + id * 0x2ec + 0x14) = 0x23;
        *(int *)(*(int *)(unsigned)&d2_Objs + id * 0x2ec + 0x60) = 1;
